#include <bits/stdc++.h>
#include <json.hpp>
using namespace std; using J=nlohmann::json; using K=tuple<int,int,int>;
struct G{int s,f,t,ve,c;};
bool sub(vector<int>a,vector<int>b){int p[9]={};for(int x:b)while(x){int k=31-__builtin_clz(x);if(p[k])x^=p[k];else{p[k]=x;break;}}for(int x:a)while(x){int k=31-__builtin_clz(x);if(!p[k])return false;x^=p[k];}return true;}
int det(array<int,3>a,array<int,3>b,array<int,3>c){return a[0]*(b[1]*c[2]-b[2]*c[1])-a[1]*(b[0]*c[2]-b[2]*c[0])+a[2]*(b[0]*c[1]-b[1]*c[0]);}
int main(int ac,char**av){try{J c,stars;ifstream(av[1])>>c;ifstream(av[2])>>stars;int v=c["v"],n=2*v+c["R"].get<int>();vector<vector<int>>F=c["frames"]; vector<int>ini=c["start"],fin=c["final"],ver(n);vector<vector<G>>ys(v),paths(v);vector<vector<int>> reads(v);int tid=0,split,S=-1;for(string phase:{"A","B"}){if(phase=="B")split=tid;for(auto e:c[phase]){for(auto z:e[3]){int t=e[0]=="in"?e[2].get<int>():z[0].get<int>(),s=e[0]=="in"?z[0].get<int>():e[2].get<int>();if(phase=="B"){G g{s,e[1],tid,ver[s],z[1].get<int>()*(12/z[2].get<int>())};if(v<=s&&s<2*v){paths[s-v].push_back(g);reads[s-v].push_back(tid);if(e[1]==0&&S<0){}else{} }if(v<=t&&t<2*v){paths[t-v].push_back(g);if(!(v<=s&&s<2*v))ys[t-v].push_back(g);}if(S<0&&e[1]!=0)S=tid-1;}ver[t]++;}tid++;}}
vector<vector<bool>>ss(F.size(),vector<bool>(F.size()));for(int a=0;a<(int)F.size();a++)for(int b=0;b<(int)F.size();b++)ss[a][b]=sub(F[a],F[b]);long double w[10]={};for(int r=1;r<=9;r++)w[r]=powl((long double)r/73,1-.0010025L)+1e-16L*32*73*73*powl(1.L/73,1-.0010025L);
vector<map<int,int>>old(v);for(int i=0;i<v;i++){int f=ini[v+i];for(auto g:paths[i]){if(f!=g.f)old[i][F[g.f].size()-F[f].size()]++;f=g.f;}if(f!=fin[v+i])old[i][F[fin[v+i]].size()-F[f].size()]++;}
vector<array<int,3>>basis;for(int a=-1;a<=1;a++)for(int b=-1;b<=1;b++)for(int d=-1;d<=1;d++)if(a||b||d){array<int,3>row{a,b,d};for(int x:row)if(x){if(x>0)basis.push_back(row);break;}}
vector<array<int,3>>mat;for(int a=0;a<(int)basis.size();a++)for(int b=a+1;b<(int)basis.size();b++)for(int d=b+1;d<(int)basis.size();d++)if(abs(det(basis[a],basis[b],basis[d]))==1)mat.push_back({a,b,d});
set<array<int,3>>triples;for(int i=0;i<v;i++)for(int j=i+1;j<v;j++)for(int k=j+1;k<v;k++)triples.insert({i,j,k});
long long attempts=0,legal=0,positive=0;long double best=0;J bestj;auto begin=chrono::steady_clock::now();
for(auto tri:triples){if(chrono::duration<double>(chrono::steady_clock::now()-begin).count()>300)break;set<int>cuts;for(int i:tri)for(auto g:ys[i])cuts.insert(g.t);for(int cut:cuts){bool exposed=false;for(int i:tri)for(int t:reads[i])if(S<t&&t<=cut)exposed=true;if(exposed)continue;array<map<K,pair<int,G>>,3>rows;array<int,3>cur,nxt;for(int a=0;a<3;a++){int i=tri[a];cur[a]=ini[v+i];nxt[a]=fin[v+i];for(auto g:ys[i]){if(g.t<=cut){auto&z=rows[a][{g.s,g.ve,g.f}];z.first+=g.c;z.second=g;cur[a]=g.f;}else{nxt[a]=g.f;break;}}}for(int E=0;E<(int)F.size();E++){bool ok=true;for(int a=0;a<3;a++)if(!ss[cur[a]][E]||!ss[E][nxt[a]])ok=false;if(!ok||F[E].empty()||F[E].size()>=9)continue;attempts++;vector<long double>price(basis.size(),1000);vector<map<int,int>>hist(basis.size());for(int b=0;b<(int)basis.size();b++){map<K,pair<int,G>>r;for(int a=0;a<3;a++)if(basis[b][a])for(auto[key,z]:rows[a]){auto&x=r[key];x.first+=basis[b][a]*z.first;x.second=z.second;}vector<G>seq;for(auto[key,z]:r)if(z.first)seq.push_back(z.second);sort(seq.begin(),seq.end(),[](G a,G b){return a.t<b.t||(a.t==b.t&&a.s<b.s);});int f=0;bool good=true;for(auto g:seq){if(!ss[f][g.f]){good=false;break;}if(f!=g.f)hist[b][F[g.f].size()-F[f].size()]++;f=g.f;}if(!good||!ss[f][E])continue;if(f!=E)hist[b][F[E].size()-F[f].size()]++;long double val=0;for(auto[r,z]:hist[b])if(r)val+=w[r]*z;price[b]=val;}
map<int,int>suffix;for(int i:tri){for(auto[r,z]:old[i])suffix[r]-=z;int f=E;for(auto g:paths[i])if(g.t>cut){if(!ss[f][g.f])throw runtime_error("suffix");if(f!=g.f)suffix[F[g.f].size()-F[f].size()]++;f=g.f;}if(f!=fin[v+i])suffix[F[fin[v+i]].size()-F[f].size()]++;}long double off=0;for(auto[r,z]:suffix)if(r)off+=w[r]*z;
for(auto m:mat){long double val=off+price[m[0]]+price[m[1]]+price[m[2]];if(val>999)continue;legal++;if(val>=-1e-14L)continue;positive++;map<int,int>dh=suffix;for(int b:m)for(auto[r,z]:hist[b])dh[r]+=z;J h=J::object();int mass=0;for(auto[r,z]:dh)if(r&&z){h[to_string(r)]=z;mass+=r*z;}if(mass)throw runtime_error("mass");if(val<best){best=val;bestj={{"targets",J::array({tri[0]+v,tri[1]+v,tri[2]+v})},{"cut_group",cut},{"recovery_frame",E},{"basis",J::array({basis[m[0]],basis[m[1]],basis[m[2]]})},{"histogram_delta",h},{"paid_moment_delta",double(val)}};cout<<bestj.dump()<<endl;}}
}}}
J out={{"scope","GL3 entries -1,0,1 determinant +/-1 inserted after initial existing signed setups; every unordered triple; common inherited recovery frames; source target reads forbidden in window; all output paths priced; discovery nomination only"},{"triples_total",triples.size()},{"recovery_attempts",attempts},{"legal_bases",legal},{"positive_bases",positive},{"best",bestj},{"best_delta",double(best)},{"seconds",chrono::duration<double>(chrono::steady_clock::now()-begin).count()}};ofstream(av[3])<<out.dump(2)<<endl;cout<<out.dump(2)<<endl;
}catch(exception&e){cerr<<e.what()<<endl;return 1;}}
